UPDATE sales_guides SET body = replace(body, '<li><strong>Áskrift</strong> — fast mánaðargjald sem innifelur allt: kerfið, hýsinguna, vöktun, öryggisuppfærslur og breytingar. Andstæðan við tímagjald.</li>', '<li><strong>Uppsetningargjald</strong> — greitt einu sinni fyrir að setja kerfið upp og flytja gögnin yfir. Fast verð eftir þrepi, aldrei tímagjald.</li>
