UPDATE sales_guides SET body = replace(body, '<p>Allir viðskiptavinir keyra sama kjarnann. Það þýðir að endurbætur og öryggisuppfærslur berast öllum, sjálfkrafa — enginn situr eftir á gamalli útgáfu. Ofan á kjarnann fær hver viðskiptavinur <strong>sérsniðnar einingar</strong>: viðbætur sem passa nákvæmlega hans rekstri. Gervigreind smíðar þær og viðheldur þeim, og þess vegna kosta þær áskrift en ekki ráðgjafatíma. Hver viðskiptavinur er með sína eigin uppsetningu og sinn eigin gagnagrunn — gögnin hans blandast aldrei við annarra.</p>
<h2>Allt innifalið í áskriftinni</h2>
<p>Fasta mánaðargjaldið innifelur kerfið sjálft, hýsingu í skýinu, vöktun, öryggisuppfærslur — og <strong>breytingar</strong>. Breytingabeiðnir eru afgreiddar á dögum, ekki mánuðum: svar innan eins virks dags, smábreytingar innan viku. Engir tímareikningar, aldrei. Það er stærsti munurinn á okkur og hefðbundinni vefstofu eða kerfissala.</p>', '<p>Allir viðskiptavinir keyra sama kjarnann. Það þýðir að endurbætur og öryggisuppfærslur berast öllum, sjálfkrafa — enginn situr eftir á gamalli útgáfu. Ofan á kjarnann fær hver viðskiptavinur <strong>sérsniðnar einingar</strong>: viðbætur sem passa nákvæmlega hans rekstri. Gervigreind smíðar þær og viðheldur þeim, og þess vegna eru þær greiddar með verkeiningum úr þjónustusamningnum en ekki með ráðgjafatímum. Hver viðskiptavinur er með sína eigin uppsetningu og sinn eigin gagnagrunn — gögnin hans blandast aldrei við annarra.</p>
<h2>Hvað viðskiptavinurinn greiðir</h2>
<p>Tvennt: <strong>uppsetningargjald</strong> einu sinni, fyrir að setja kerfið upp og flytja gögnin yfir, og <strong>þjónustusamning</strong> á föstu mánaðargjaldi. Samningurinn innifelur hýsingu í skýinu, vöktun, öryggisuppfærslur og ákveðinn fjölda <strong>verkeininga</strong> á mánuði fyrir breytingar og sérsmíði. Breytingabeiðnir eru afgreiddar á dögum, ekki mánuðum: svar innan eins virks dags, smábreytingar innan viku. Engir tímareikningar, aldrei. Það er stærsti munurinn á okkur og hefðbundinni vefstofu eða kerfissala. Verðin og reglurnar um verkeiningar eru í leiðinni <em>Þrepin þrjú</em>.</p>')
       WHERE slug = 'kerfid-i-stuttu-mali' AND updated_by IS NULL
         AND position('<p>Allir viðskiptavinir keyra sama kjarnann. Það þýðir að endurbætur og öryggisuppfærslur berast öllum, sjálfkrafa — enginn situr eftir á gamalli útgáfu. Ofan á kjarnann fær hver viðskiptavinur <strong>sérsniðnar einingar</strong>: viðbætur sem passa nákvæmlega hans rekstri. Gervigreind smíðar þær og viðheldur þeim, og þess vegna kosta þær áskrift en ekki ráðgjafatíma. Hver viðskiptavinur er með sína eigin uppsetningu og sinn eigin gagnagrunn — gögnin hans blandast aldrei við annarra.</p>
