UPDATE sales_guides SET body = replace(body, '<p>Ef þú hefur bara eina mínútu: <em>„Þið eruð sennilega með þrjú, fjögur kerfi og jafn marga reikninga — og þegar ykkur vantar breytingu bíðið þið vikum saman eða borgið tímagjald. Við setjum þetta allt í eitt íslenskt kerfi á föstu mánaðargjaldi, og þegar ykkur vantar breytingu er hún afgreidd á dögum. Sérsniðið kostar áskrift, ekki ráðgjafatíma.“</em></p>', '<p>Ef þú hefur bara eina mínútu: <em>„Þið eruð sennilega með þrjú, fjögur kerfi og jafn marga reikninga — og þegar ykkur vantar breytingu bíðið þið vikum saman eða borgið tímagjald. Við setjum þetta allt í eitt íslenskt kerfi: eitt uppsetningargjald og svo einn þjónustusamningur á föstu mánaðargjaldi. Þegar ykkur vantar breytingu er hún metin fyrir fram og afgreidd á dögum. Sérsniðið kostar verkeiningar, ekki ráðgjafatíma.“</em></p>')
       WHERE slug = 'solusagan' AND updated_by IS NULL
         AND position('<p>Ef þú hefur bara eina mínútu: <em>„Þið eruð sennilega með þrjú, fjögur kerfi og jafn marga reikninga — og þegar ykkur vantar breytingu bíðið þið vikum saman eða borgið tímagjald. Við setjum þetta allt í eitt íslenskt kerfi á föstu mánaðargjaldi, og þegar ykkur vantar breytingu er hún afgreidd á dögum. Sérsniðið kostar áskrift, ekki ráðgjafatíma.“</em></p>' in body) > 0 AND position('<p>Ef þú hefur bara eina mínútu: <em>„Þið eruð sennilega með þrjú, fjögur kerfi og jafn marga reikninga — og þegar ykkur vantar breytingu bíðið þið vikum saman eða borgið tímagjald. Við setjum þetta allt í eitt íslenskt kerfi: eitt uppsetningargjald og svo einn þjónustusamningur á föstu mánaðargjaldi. Þegar ykkur vantar breytingu er hún metin fyrir fram og afgreidd á dögum. Sérsniðið kostar verkeiningar, ekki ráðgjafatíma.“</em></p>' in body) = 0;

UPDATE sales_guides SET summary = replace(summary, 'Vefur (39), Verslun (59) og Rekstur (79) þ.kr./mán — öll verð DRÖG þar til Halli staðfestir. Flöt áskrift, aldrei tímagjald; uppsetningargjald fellur niður með árssamningi. Hér lærirðu að para fyrirtæki við rétt þrep.', 'Vefur, Verslun og Rekstur: uppsetningargjald 390 / 580 / 690 þ.kr. og þjónustusamningur 19 / 29 / 39 þ.kr./mán með 5 / 10 / 20 verkeiningum á mánuði — öll verð DRÖG þar til Halli staðfestir, öll án VSK. Aldrei tímagjald. Hér lærirðu verðmódelið, hvað verkeining er og hvernig þú parar fyrirtæki við rétt þrep.')
