UPDATE sales_guides SET body = replace(body, '<h2>Árssamningurinn og endurnýjun</h2>
<p>Munaðu að árssamningur er hagstæðastur fyrir báða: viðskiptavinurinn slapp við uppsetningargjaldið og við fáum fyrirsjáanleika. Þegar líður að endurnýjun áttu að vita stöðuna á sambandinu löngu áður en dagsetningin rennur upp — það er afrakstur mánaðarlegu samtalanna. Öll umræða um verð eða samningskjör við endurnýjun fer til Halla, eins og alltaf.</p>', '<h2>Samningstíminn og endurnýjun</h2>
<p>Í drögum að þjónustusamningi gildir samningurinn í 12 mánuði frá því kerfið fer í loftið og endurnýjast svo sjálfkrafa um 12 mánuði í senn (DRÖG — lögfræðingur á eftir að fara yfir samninginn og Halli staðfestir). Fylgstu líka með einingunum: viðskiptavinur sem klárar einingar mánaðarins aftur og aftur gæti átt betur heima í þrepinu fyrir ofan — skráðu það og láttu Halla vita. Þegar líður að endurnýjun áttu að vita stöðuna á sambandinu löngu áður en dagsetningin rennur upp — það er afrakstur mánaðarlegu samtalanna. Öll umræða um verð eða samningskjör við endurnýjun fer til Halla, eins og alltaf.</p>')
       WHERE slug = 'manadarleg-samskipti' AND updated_by IS NULL
         AND position('<h2>Árssamningurinn og endurnýjun</h2>
<p>Munaðu að árssamningur er hagstæðastur fyrir báða: viðskiptavinurinn slapp við uppsetningargjaldið og við fáum fyrirsjáanleika. Þegar líður að endurnýjun áttu að vita stöðuna á sambandinu löngu áður en dagsetningin rennur upp — það er afrakstur mánaðarlegu samtalanna. Öll umræða um verð eða samningskjör við endurnýjun fer til Halla, eins og alltaf.</p>' in body) > 0 AND position('<h2>Samningstíminn og endurnýjun</h2>
<p>Í drögum að þjónustusamningi gildir samningurinn í 12 mánuði frá því kerfið fer í loftið og endurnýjast svo sjálfkrafa um 12 mánuði í senn (DRÖG — lögfræðingur á eftir að fara yfir samninginn og Halli staðfestir). Fylgstu líka með einingunum: viðskiptavinur sem klárar einingar mánaðarins aftur og aftur gæti átt betur heima í þrepinu fyrir ofan — skráðu það og láttu Halla vita. Þegar líður að endurnýjun áttu að vita stöðuna á sambandinu löngu áður en dagsetningin rennur upp — það er afrakstur mánaðarlegu samtalanna. Öll umræða um verð eða samningskjör við endurnýjun fer til Halla, eins og alltaf.</p>' in body) = 0;

